-- 1. Add column with constant default (instantaneous metadata change in PG 11+)
ALTER TABLE users 
ADD COLUMN is_verified BOOLEAN NOT NULL DEFAULT false;

-- 2. Rename column (instant metadata change)
ALTER TABLE users 
RENAME COLUMN is_verified TO email_verified;

-- 3. Change column type using explicit cast expression
ALTER TABLE metrics 
ALTER COLUMN count TYPE BIGINT USING count::BIGINT;
